/* Original, non-graphic fictional war prologue. Canvas effects; no video/network dependency. */
const ExoStory=(()=>{
 const chapters=[
  {tag:'01 / THE SILENCE',title:'失联的那一夜，边境再也没有了和平。',line:'公元 2189 年，外环殖民地的中继网络相继熄灭。护航舰队奉命前往 ECHO–9，寻找失联信号。',speaker:'航行档案 · 第七勘探舰队',scene:'orbit'},
  {tag:'02 / FIRST CONTACT',title:'它们不是来回应我们的。',line:'陌生舰群从行星阴影中出现。通讯被干扰，护航舰遭到攻击。没有宣战，也没有警告。战争就这样开始了。',speaker:'舰桥通讯 · 舰队遭遇伏击',scene:'battle'},
  {tag:'03 / LAST DIRECTIVE',title:'“别回头。把希望送到地面。”',line:'母舰将最后一台勘探机甲投入逃生舱。它还不认识这颗星球。现在，只有你能带它探索，教它判断危险、寻找出路。',speaker:'舰长 · 最后指令',scene:'escape'},
  {tag:'04 / EXO PROTOCOL',title:'战火还在头顶。你的任务，从地面开始。',line:'你在外星荒原醒来。寻找失联者留下的线索，修复受损的机甲。先亲自走过这片荒原，再教它学会独立行动。',speaker:'EV–04 · 紧急启动',scene:'surface'}
 ];let frame=0,active=false,index=-1,start=0,canvas,ctx,container,onDone,paused=false,pauseAt=0,reduced=false;
 function stop(){active=false;cancelAnimationFrame(frame)}
 function ship(g,x,y,s,enemy=false){g.save();g.translate(x,y);g.scale(s,s);g.fillStyle=enemy?'#473b44':'#748792';g.beginPath();g.moveTo(75,0);g.lineTo(12,-15);g.lineTo(-50,-24);g.lineTo(-33,-7);g.lineTo(-61,0);g.lineTo(-33,8);g.lineTo(-50,24);g.lineTo(12,15);g.closePath();g.fill();g.strokeStyle=enemy?'#cd867d':'#b6d4df';g.lineWidth=1;g.stroke();g.fillStyle='#202f3d';g.fillRect(-12,-8,43,16);g.fillStyle=enemy?'#fc836c':'#87ddec';g.fillRect(-51,-4,15,8);g.fillStyle=enemy?'#e66d5b55':'#70cbef66';g.beginPath();g.moveTo(-50,-6);g.lineTo(-90,0);g.lineTo(-50,6);g.fill();g.restore()}
 function setChapter(i){index=i;const c=chapters[i];container.className='exo-cinema story-'+c.scene;document.getElementById('story-tag').textContent=c.tag;document.getElementById('story-title').textContent=c.title;document.getElementById('story-line').textContent=c.line;document.getElementById('story-speaker').textContent=c.speaker;document.getElementById('story-next').textContent=i===3?'开始驾驶 →':'下一幕 →';document.getElementById('story-progress').style.width=(i+1)*25+'%'}
 function draw(t){const r=canvas.getBoundingClientRect(),w=r.width,h=r.height,d=Math.min(2,window.devicePixelRatio||1);if(canvas.width!==Math.round(w*d)||canvas.height!==Math.round(h*d)){canvas.width=Math.round(w*d);canvas.height=Math.round(h*d)}ctx.setTransform(d,0,0,d,0,0);ctx.clearRect(0,0,w,h);const movement=reduced?0:t;
  if(index<3){for(let i=0;i<4;i++)ship(ctx,w*(.19+i*.13)+(movement*9)%70,h*(.28+i*.057),(.55+i*.18)*Math.min(1,w/700));}
  if(index===1){for(let i=0;i<3;i++){ctx.save();ctx.translate(w*(.78+i*.05)-movement*9,h*(.2+i*.13));ctx.rotate(Math.PI);ship(ctx,0,0,.6*Math.min(1,w/700),true);ctx.restore()}for(let i=0;i<7;i++){const u=((movement*.35+i*.137)%1);ctx.strokeStyle=i%2?'#df9776aa':'#8fd2e3aa';ctx.lineWidth=1.5;ctx.beginPath();const x=w*(.7-u*.5),y=h*(.2+i*.045+u*.13);ctx.moveTo(x,y);ctx.lineTo(x+35,y-8);ctx.stroke()}const q=(movement%3)/3;ctx.fillStyle=`rgba(246,160,94,${(1-q)*.3})`;ctx.beginPath();ctx.arc(w*.38,h*.36,5+q*40,0,7);ctx.fill()}
  if(index===2){const u=Math.min(1,movement/7);ctx.save();ctx.translate(w*(.28+u*.4),h*(.2+u*.38));ctx.rotate(.65);ship(ctx,0,0,.5+u*.3);ctx.strokeStyle='#98dbeb55';ctx.beginPath();ctx.moveTo(-20,0);ctx.lineTo(-200,0);ctx.stroke();ctx.restore()}
  if(index===3){ctx.strokeStyle='#a8dae77a';ctx.lineWidth=1;const x=w*.65,y=h*.37;ctx.beginPath();ctx.arc(x,y,55,0,7);ctx.moveTo(x-75,y);ctx.lineTo(x+75,y);ctx.moveTo(x,y-75);ctx.lineTo(x,y+75);ctx.stroke();ctx.fillStyle='#c5dde3';ctx.font='11px monospace';ctx.fillText('EV–04 / SIGNAL RESTORED',x-70,y+85)}
 }
 function tick(now){if(!active)return;if(!paused){const total=(now-start)/1000,next=Math.min(3,Math.floor(total/7));if(next!==index)setChapter(next);draw(total-index*7);if(total>=28&&!reduced){finish();return}}frame=requestAnimationFrame(tick)}
 function finish(){stop();onDone()}
 function begin(done,reduce=false){stop();onDone=done;reduced=reduce;paused=reduce;active=true;index=-1;document.getElementById('app').innerHTML=`<main class="exo"><section id="exo-cinema" class="exo-cinema"><div class="story-background"></div><canvas id="story-canvas" aria-hidden="true"></canvas><div class="story-letterbox"></div><div class="story-top"><span>EXO / 远星协议 · 序章</span><div><button id="story-pause" onclick="ExoStory.pause()">${reduce?'播放':'暂停'}</button><button onclick="ExoStory.finish()">跳过序章 →</button></div></div><div class="story-copy" aria-live="polite"><span id="story-tag" class="exo-tag"></span><h1 id="story-title"></h1><div id="story-speaker"></div><p id="story-line"></p><button id="story-next" onclick="ExoStory.next()">下一幕 →</button></div><div class="story-progress"><i id="story-progress"></i></div></section></main>`;container=document.getElementById('exo-cinema');canvas=document.getElementById('story-canvas');ctx=canvas.getContext('2d');start=performance.now();pauseAt=start;setChapter(0);draw(0);frame=requestAnimationFrame(tick)}
 function next(){if(!active)return;if(index===3){finish();return}setChapter(index+1);start=performance.now()-index*7000;pauseAt=performance.now();draw(0)}
 function pause(){if(!active)return;if(paused){start+=performance.now()-pauseAt;paused=false}else{paused=true;pauseAt=performance.now()}document.getElementById('story-pause').textContent=paused?'播放':'暂停'}
 return {begin,stop,next,pause,finish,chapters};
})();
